// Each chapter's question bank is its own lazily-loaded chunk (dynamic import), so the
// app only downloads the chapters you actually open. Chapter question COUNTS (used by the
// home screens) live in ./counts.js, which is generated by `npm run gen:counts` — it runs
// automatically before `npm run dev` and `npm run build`.
//
// Question schema:
// { id, type, question, options[], correctIndex, explanation, difficulty }
//
// To add a chapter: create banks/<file>.js exporting the array, then add a line to LOADERS.

import { QUESTION_COUNTS } from './counts';
import { balanceOptions } from '../balanceOptions';

export const LOADERS = {
  'biological-classification': () => import('./banks/biologicalClassification').then(m => m.BIOLOGICAL_CLASSIFICATION),
  'living-world': () => import('./banks/livingWorld').then(m => m.LIVING_WORLD),
  'respiration-plants': () => import('./banks/respirationPlants').then(m => m.RESPIRATION_PLANTS),
  'photosynthesis': () => import('./banks/photosynthesis').then(m => m.PHOTOSYNTHESIS),
  'ecosystem': () => import('./banks/ecosystem').then(m => m.ECOSYSTEM),
  'evolution': () => import('./banks/evolution').then(m => m.EVOLUTION),
  'biotech-principles': () => import('./banks/biotechPrinciples').then(m => m.BIOTECH_PRINCIPLES),
  'biotech-applications': () => import('./banks/biotechApplications').then(m => m.BIOTECH_APPLICATIONS),
  'cell-unit-of-life': () => import('./banks/cellUnitOfLife').then(m => m.CELL_UNIT_OF_LIFE),
  'cell-cycle-division': () => import('./banks/cellCycleDivision').then(m => m.CELL_CYCLE_DIVISION),
  'animal-kingdom': () => import('./banks/animalKingdom').then(m => m.ANIMAL_KINGDOM),
  'biodiversity-conservation': () => import('./banks/biodiversityConservation').then(m => m.BIODIVERSITY_CONSERVATION),
  'plant-kingdom': () => import('./banks/plantKingdom').then(m => m.PLANT_KINGDOM),
  'human-reproduction': () => import('./banks/humanReproduction').then(m => m.HUMAN_REPRODUCTION),
  'reproductive-health': () => import('./banks/reproductiveHealth').then(m => m.REPRODUCTIVE_HEALTH),
  'locomotion-movement': () => import('./banks/locomotionMovement').then(m => m.LOCOMOTION_MOVEMENT),
  'breathing-exchange-gases': () => import('./banks/breathingExchangeGases').then(m => m.BREATHING_EXCHANGE_GASES),
  'body-fluids-circulation': () => import('./banks/BodyFluidsCirculation').then(m => m.BODY_FLUIDS_CIRCULATION),
  'excretory-products-elimination': () => import('./banks/excretoryProductsElimination').then(m => m.EXCRETORY_PRODUCTS_ELIMINATION),
  'neural-control-coordination': () => import('./banks/neuralControlCoordination').then(m => m.NEURAL_CONTROL_COORDINATION),
  'chemical-coordination-integration': () => import('./banks/chemicalCoordinationIntegration').then(m => m.CHEMICAL_COORDINATION_INTEGRATION),
  'morphology-flowering-plants': () => import('./banks/morphologyFloweringPlant').then(m => m.MORPHOLOGY_FLOWERING_PLANTS),
  'anatomy-flowering-plants': () => import('./banks/anatomyFloweringPlants').then(m => m.ANATOMY_FLOWERING_PLANTS),
  'biomolecules': () => import('./banks/biomolecules').then(m => m.BIOMOLECULES),
  'microbes-human-welfare': () => import('./banks/microbesHumanWelfare').then(m => m.MICROBES_HUMAN_WELFARE),
  'structural-organisation-animals': () => import('./banks/structuralOrganisationAnimals').then(m => m.STRUCTURAL_ORGANISATION_ANIMALS),
  'plant-growth-development': () => import('./banks/plantGrowthDevelopment').then(m => m.PLANT_GROWTH_DEVELOPMENT),
  'sexual-reproduction-plants': () => import('./banks/sexualReproductionPlants').then(m => m.SEXUAL_REPRODUCTION_PLANTS),
  'principle-inheritance-variation': () => import('./banks/principleInheritanceVariation').then(m => m.PRINCIPLE_INHERITANCE_VARIATION),
  'molecular-basis-inheritance': () => import('./banks/molecularBasisInheritance').then(m => m.MOLECULAR_BASIS_INHERITANCE),
  'organisms-populations': () => import('./banks/organismsPopulations').then(m => m.ORGANISMS_POPULATIONS),
  'human-health-disease': () => import('./banks/humanHealthDisease').then(m => m.HUMAN_HEALTH_DISEASE),
};

const cache = {};

// Resolves to the chapter's question array ([] if the chapter has no bank).
export function getChapterQuestions(chapterId) {
  const load = LOADERS[chapterId];
  if (!load) return Promise.resolve([]);
  if (!cache[chapterId]) {
    cache[chapterId] = load().then(qs => balanceOptions(qs, chapterId)).catch((err) => {
      delete cache[chapterId]; // allow a retry after a failed chunk download
      throw err;
    });
  }
  return cache[chapterId];
}

// Synchronous count for chapter cards / "chapters live" — no bank is downloaded.
export function getChapterQuestionCount(chapterId) {
  return QUESTION_COUNTS[chapterId] || 0;
}
